import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.D_QzxFIp.js";const k=JSON.parse('{"title":"Webhook Events","description":"","frontmatter":{"title":"Webhook Events"},"headers":[],"relativePath":"reference/webhook-events.md","filePath":"reference/webhook-events.md"}'),o={name:"reference/webhook-events.md"};function n(d,e,h,r,l,c){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="webhook-events" tabindex="-1">Webhook Events <a class="header-anchor" href="#webhook-events" aria-label="Permalink to &quot;Webhook Events&quot;">​</a></h1><p>Webhook Events API: the log of webhooks Paystack has sent to your integration&#39;s webhook URL, with their delivery status, the payload that was sent and what your endpoint answered, and a way to send them again. Use it to find out whether a webhook was delivered, to see exactly what Paystack sent, and to recover events your endpoint missed.</p><p><code>list</code>, <code>lookup</code> and <code>fetch</code> only read. <code>resend</code> and <code>resend_matching</code> make Paystack deliver webhooks to your endpoint again, and have <strong>not</strong> been called against the Paystack test API.</p><p>Use it as <code>client.webhook_events</code>. Every method takes keyword arguments, returns a <a href="/paystack_sdk/next/reference/response"><code>PaystackSdk::Response</code></a>, and raises a <code>PaystackSdk::Error</code> if a parameter is invalid before anything is sent. An unsuccessful result from Paystack (a 400 or 404) comes back as a Response with <code>success?</code> false.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="list" tabindex="-1"><code>list</code> <a class="header-anchor" href="#list" aria-label="Permalink to &quot;`list`&quot;">​</a></h3><div class="language-ruby vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light night-owl vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">webhook_events.</span><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#82AAFF;--shiki-dark-font-style:italic;">list</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">(</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">  category</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">  event_type</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">  status</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">  category_row_id</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">  from</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">  to</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">  limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">  next_cursor</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">  previous</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">)</span></span></code></pre></div><p>List Events.</p><p>Fetches a page of the webhook events sent to your integration, newest first. The response <code>meta</code> holds <code>next</code> and <code>previous</code> cursors: pass <code>meta.next</code> back as <code>next_cursor:</code> for the next page.</p><p>Observed on the Paystack test API (2026-10-09), where the docs differ: a page holds 50 events by default (the docs say 20), <code>limit</code> is capped at 50, and a <code>limit</code> that is not a number is ignored.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>category</code></td><td>String</td><td></td><td>Filter by category, for example &quot;transactions&quot; or &quot;refund&quot;.</td></tr><tr><td><code>event_type</code></td><td>String</td><td></td><td>Filter by event name, for example &quot;charge.success&quot;.</td></tr><tr><td><code>status</code></td><td>String</td><td></td><td>Filter by delivery status: Delivered, Pending or Failed.</td></tr><tr><td><code>category_row_id</code></td><td>String, Integer</td><td></td><td>Filter by the ID of the resource the event is about, such as a transaction ID.</td></tr><tr><td><code>from</code></td><td>String, Time, Date</td><td></td><td>Only events from this time on, for example 2016-09-24T00:00:05.000Z or 2016-09-21.</td></tr><tr><td><code>to</code></td><td>String, Time, Date</td><td></td><td>Only events up to this time.</td></tr><tr><td><code>limit</code></td><td>Integer</td><td></td><td>How many events to return per page.</td></tr><tr><td><code>next_cursor</code></td><td>String</td><td></td><td>The <code>meta.next</code> cursor of a previous response (sent as <code>next</code>). Not together with <code>previous</code>.</td></tr><tr><td><code>previous</code></td><td>String</td><td></td><td>The <code>meta.previous</code> cursor of a previous response. Not together with <code>next_cursor</code>.</td></tr></tbody></table><p>Paystack docs: <a href="https://paystack.com/docs/api/webhook-events/#list" target="_blank" rel="noreferrer">https://paystack.com/docs/api/webhook-events/#list</a></p><h3 id="lookup" tabindex="-1"><code>lookup</code> <a class="header-anchor" href="#lookup" aria-label="Permalink to &quot;`lookup`&quot;">​</a></h3><div class="language-ruby vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light night-owl vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">webhook_events.</span><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#82AAFF;--shiki-dark-font-style:italic;">lookup</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">id</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">)</span></span></code></pre></div><p>Look Up an Event.</p><p>Finds a webhook event by its own ID, or by the ID of the resource it is about (a transaction ID, not the transaction&#39;s reference). Observed on the test API: an event&#39;s <code>_id</code> and a <code>category_row_id</code> both match; a value that matches nothing is a 404 &quot;Webhook not found&quot; (an unsuccessful Response).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>String, Integer</td><td>yes</td><td>An event <code>_id</code>, or the ID of the resource it is about. Sent as <code>reference</code>, the name Paystack&#39;s docs give it, although it is not a reference.</td></tr></tbody></table><p>Paystack docs: <a href="https://paystack.com/docs/api/webhook-events/#lookup" target="_blank" rel="noreferrer">https://paystack.com/docs/api/webhook-events/#lookup</a></p><h3 id="fetch" tabindex="-1"><code>fetch</code> <a class="header-anchor" href="#fetch" aria-label="Permalink to &quot;`fetch`&quot;">​</a></h3><div class="language-ruby vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light night-owl vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">webhook_events.</span><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#82AAFF;--shiki-dark-font-style:italic;">fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">id</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">)</span></span></code></pre></div><p>Fetch Event.</p><p>Gets one event in full: <code>event_payload</code> (the body Paystack sent), <code>webhook_url</code>, <code>status</code>, <code>status_detail</code>, <code>response_code</code>, <code>merchant_response_body</code> (what your endpoint answered), <code>trial_count</code> and <code>trials</code>. Observed on the test API, where <code>event_payload</code> is a Hash with the keys <code>event</code> and <code>data</code>. Read the payload&#39;s own <code>data</code> with brackets, <code>response.event_payload[:data]</code>: dot access <code>event_payload.data</code> returns the Response itself, because <code>Response#data</code> is a method.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>String</td><td>yes</td><td>The event&#39;s <code>_id</code>, from an item of <code>#list</code>.</td></tr></tbody></table><p>Paystack docs: <a href="https://paystack.com/docs/api/webhook-events/#fetch" target="_blank" rel="noreferrer">https://paystack.com/docs/api/webhook-events/#fetch</a></p><h3 id="resend" tabindex="-1"><code>resend</code> <a class="header-anchor" href="#resend" aria-label="Permalink to &quot;`resend`&quot;">​</a></h3><div class="language-ruby vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light night-owl vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">webhook_events.</span><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#82AAFF;--shiki-dark-font-style:italic;">resend</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">ids</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">)</span></span></code></pre></div><p>Resend Events.</p><p>Asks Paystack to deliver a specific set of events to your current webhook URL again.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>ids</code></td><td>Array&lt;String&gt;</td><td>yes</td><td>The <code>_id</code>s of the events to resend: not empty, at most 100.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Note</p><p>This makes Paystack send webhooks to your endpoint. The docs say resending is not idempotent: sending the same event ID twice delivers it twice, so your endpoint must dedupe. It has not been called against the Paystack test API; the method follows the docs.</p></div><p>Paystack docs: <a href="https://paystack.com/docs/api/webhook-events/#resend" target="_blank" rel="noreferrer">https://paystack.com/docs/api/webhook-events/#resend</a></p><h3 id="resend-matching" tabindex="-1"><code>resend_matching</code> <a class="header-anchor" href="#resend-matching" aria-label="Permalink to &quot;`resend_matching`&quot;">​</a></h3><div class="language-ruby vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ruby</span><pre class="shiki shiki-themes github-light night-owl vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">webhook_events.</span><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#82AAFF;--shiki-dark-font-style:italic;">resend_matching</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">preview</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#7FDBCA;">filters</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#82AAFF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#D6DEEB;">)</span></span></code></pre></div><p>Resend Matching Events.</p><p>Asks Paystack to deliver every event that matches the filters to your current webhook URL again. With <code>preview: true</code> it only counts the matching events.</p><p><code>preview:</code> has no default here, although the docs make it optional: with no filters this resends every event, so you have to say which you mean. Call it with <code>preview: true</code> first.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>preview</code></td><td>Boolean</td><td>yes</td><td>true to return the matching count without resending anything; false to resend.</td></tr><tr><td><code>filters</code></td><td>Hash, nil</td><td></td><td>Any of the <code>#list</code> filters: category, event_type, status, category_row_id, from, to.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Note</p><p>This can make Paystack send a lot of webhooks to your endpoint, which must dedupe. It has not been called against the Paystack test API, including with <code>preview: true</code>; the method follows the docs.</p></div><p>Paystack docs: <a href="https://paystack.com/docs/api/webhook-events/#resend-matching" target="_blank" rel="noreferrer">https://paystack.com/docs/api/webhook-events/#resend-matching</a></p>',39)])])}const y=t(o,[["render",n]]);export{k as __pageData,y as default};
